module.exports = {"schema":1,"topic_number":46,"topic_name":"TEMA 46. SOPORTE VITAL","pdf_filename":"TEMA_46_SOPORTE_VITAL_CEIS_PARA_INDEXAR.pdf","pdf_sha256":"a72f123bbeb75a04445157be0342f135a1dbdf5657068d561db763f693590dc1","pdf_page_count":28,"images":[{"concept":"Triple maniobra modificada con inmovilización cervical","sha256":"91ce10f2b97153f1c92c69f61624a33e5589b34c5998203f5c6df4a417fc0481","base64":"","file":"T46_FIG_01_P019.png","figure":"1","printed_page":"19","source_page":"5"},{"concept":"Cinco golpes interescapulares de desobstrucción OVACE","sha256":"e427222e987facc9f95c120932b12e362b6d92a6063b9902cc5cb75f9e033926","base64":"","file":"T46_FIG_02_P034.png","figure":"2","printed_page":"34","source_page":"20"}],"questions":[{"external_key":"T46-GRAF-0001","source_pdf_page":5,"manual_page":"19","topic_pdf_page":5,"graphic_file":"T46_FIG_01_P019.png","image_sha256":"91ce10f2b97153f1c92c69f61624a33e5589b34c5998203f5c6df4a417fc0481","coverage_section":"Interpretación visual — CEIS original","coverage_concept":"Triple maniobra modificada con inmovilización cervical","stem":"En el paciente representado, si la maniobra de elevación mandibular no consigue abrir la vía aérea, ¿qué combinación de apoyos, dirección de tracción y posición cervical corresponde a la maniobra indicada por el CEIS?","options":["Ambas manos bajo los ángulos de la mandíbula, empujando hacia arriba y adelante sin hiperextender la cabeza.","Ambas manos bajo los ángulos de la mandíbula, dirigiendo la tracción hacia atrás y realizando una hiperextensión cervical controlada.","Una mano sobre la frente y los dedos índice y medio bajo el mentón, elevando éste con hiperextensión cervical.","Pulgar de una mano dentro de la boca y la otra sobre la frente, avanzando la mandíbula sin recurrir a las dos manos bajo sus ángulos."],"correct_index":0,"explanation":"CEIS, pág. 19: tras el fracaso de la elevación mandibular, la triple maniobra modificada utiliza ambas manos bajo los ángulos mandibulares, arriba y adelante, sin hiperextensión. Las otras alternativas mezclan la maniobra frente-mentón y elevación de mandíbula.","source_evidence":"Si con esta maniobra no conseguimos abrir la vía aérea, realizaremos la triple maniobra modificada: se realiza colocando las dos manos bajo los ángulos de la mandíbula, empujándola hacia arriba y adelante, manteniendo la cabeza sin hiperextensión.","question_family":"GRAFICA","difficulty":"muy alta","graphic":{"source":"CEIS original","printedPage":19,"figure":"1","questionKey":"T46-GRAF-0001"},"audit_status":"REVISADO_CEIS_IMAGEN_SIN_ROTULOS; DIFICULTAD_REAL_A_EVALUAR_EN_TEST"},{"external_key":"T46-GRAF-0002","source_pdf_page":20,"manual_page":"34","topic_pdf_page":20,"graphic_file":"T46_FIG_02_P034.png","image_sha256":"e427222e987facc9f95c120932b12e362b6d92a6063b9902cc5cb75f9e033926","coverage_section":"Interpretación visual — CEIS original","coverage_concept":"Cinco golpes interescapulares de desobstrucción OVACE","stem":"En el adulto consciente con obstrucción de la vía aérea que no puede toser, la maniobra que se observa constituye el primer paso. ¿Qué secuencia y posición corporal especifica el CEIS?","options":["Cinco compresiones abdominales con el paciente inclinado hacia delante y, después, cinco golpes interescapulares si persiste la obstrucción.","Cinco palmadas interescapulares con el talón de la mano inclinando al paciente hacia delante y, si no resuelven, cinco compresiones abdominales.","Cinco palmadas interescapulares con el paciente en posición erguida y, si persiste la obstrucción, cinco compresiones abdominales.","Cinco palmadas interescapulares inclinando al paciente hacia delante y, si no resuelven, cinco compresiones torácicas."],"correct_index":1,"explanation":"CEIS, pág. 34: en adulto consciente incapaz de toser, primero cinco palmadas interescapulares con paciente inclinado hacia delante; solo si no resuelven, cinco compresiones abdominales.","source_evidence":"Si el paciente está consciente pero no puede toser: 1. Cinco palmadas interescapulares, con el talón de la mano inclinando al paciente hacia delante. Si tras dar los cinco golpes interescapulares no se ha conseguido eliminar la obstrucción: cinco compresiones abdominales siguiendo la maniobra de Heimlich.","question_family":"GRAFICA","difficulty":"muy alta","graphic":{"source":"CEIS original","printedPage":34,"figure":"2","questionKey":"T46-GRAF-0002"},"audit_status":"REVISADO_CEIS_IMAGEN_SIN_ROTULOS; DIFICULTAD_REAL_A_EVALUAR_EN_TEST"}],"coverage_additions":[{"external_key":"T46-EJ-MA-001","concept":"Aspiración de secreciones: límite temporal y presión pediátrica","source_page":5,"manual_page":"19","section":"Datos especialmente examinables — CEIS","source_evidence":"Máximo de 5 segundos de aspiración en cada introducción; en niños la presión negativa no debe ser superior a 100 mm de Hg."},{"external_key":"T46-EJ-MA-002","concept":"OVACE: diferencia según capacidad de tos","source_page":20,"manual_page":"34","section":"Datos especialmente examinables — CEIS","source_evidence":"Si el adulto está consciente y puede toser, animar a continuar y no dar golpes en la espalda; si no puede toser, cinco palmadas interescapulares y, si no resuelven, cinco compresiones abdominales."}],"edition":"CEIS fuente única; paquete cinco temas corregido; 2026-11-08","generator_requirements":"Solo PDF CEIS 557363-2.pdf. Dificultad Muy Alta: error plausible en cifra, etapa, secuencia, destinatario o condición; no inventar otras fuentes. Estilo examen Navarra 2026 > 2024 > 2023. Los gráficos ya llevan pregunta prefabricada; nunca improvisar con la imagen."};
